questionvariables.text:
/* Design: event texts are CASText [[if]] chains, not strings. Categories of pairs 1, 3, 5, 6, 9, 11 checked by enumeration. Source: adapted from the definitions in SMP AS/A2 Statistics 1, chapter 3, sections B and D. */
CAT: ["me","me","me","me","ind","ind","ind","ind","nei","nei","nei","nei"];
TR: [[1,5,9],[10,2,6],[11,7,3],[8,12,4],[5,9,10],[2,1,11],[6,12,3],[9,4,8],[7,10,1],[12,8,5]];
ix: 1+rand(10);
i1: TR[ix][1]; i2: TR[ix][2]; i3: TR[ix][3];
k1: CAT[i1]; k2: CAT[i2]; k3: CAT[i3];
mko(c) := [["me", is(c="me"), "mutually exclusive"], ["ind", is(c="ind"), "independent"], ["nei", is(c="nei"), "neither"]];
o1: mko(k1); o2: mko(k2); o3: mko(k3);
wa(c) := if c="me" then "ind" elseif c="ind" then "nei" else "ind";
wb(c) := if c="me" then "nei" else "me";
w11: wa(k1); w12: wb(k1); w21: wa(k2); w22: wb(k2); w31: wa(k3); w32: wb(k3);
n1: if k1="me" then 1 elseif k1="ind" then 2 else 3; n2: if k2="me" then 1 elseif k2="ind" then 2 else 3; n3: if k3="me" then 1 elseif k3="ind" then 2 else 3;
